parameters.jsCode:
// Get the data from the direct input of this node
const inputText = $input.first().json.chatInput;
const sessionId = $input.first().json.sessionId ;
const jv_number = $input.first().json.jv_number;

// Get the sequence number from the "Get Sequence" node's output
// This is the correct way to reference data from another node in a Code node.
//const jv_number = $input.first().json.next_val ;

if (typeof inputText !== 'string') {
  throw new Error('Input must be a string');
}

// Concatenate the two values into a single string
// We'll use a template literal for a clean, readable result.

//const jv_number = $node["Get Sequence"].json[0].next_val;
const combinedString = `${inputText} and ${jv_number}`;

// You can now use combinedString in your output
const splitItems = inputText.split('and').map(item => item.trim());
const trantype =  splitItems.slice(0,5) ;

return splitItems.map(item => ({
  json: {
    task_name: item,
    trans_type:  item.slice(0,5).toUpperCase(),
    sessionId: sessionId,
    jv_number: jv_number,
   task_name_with_jv: item + ' JV_' +  jv_number,// Here is the new combined string
  }
}));

// This is the array of input items provided by n8n.
// Do NOT use `$input.first()` as it only gets the first item.
const parsedItems = [];

// Loop through each item provided by the previous node.
for (const item of items) {
  // Get the string from the current item's JSON data.
  // We use `item.json` to access the data for the current item in the loop.
  const inputText = item.json.task_name_with_jv;

  // Use a regular expression to find the first sequence of digits.
  const matches = inputText.match(/\d+/);

  let amountValue = null;
  if (matches && matches.length > 0) {
    // Convert the matched string (e.g., "200") to a number.
    amountValue = parseInt(matches[0], 10);
  }

  // Extract JV number from task_name (works if format like "... JV_1048")

  const match = inputText.match(/JV_(\d+)/);
  if (match) {
    item.jv_number = 'JV_' + match[1];
  }

  // Create the new output item. We are creating a new object
  // for the output of this iteration.
  const newItem = {
    // We are adding all the properties to a new `json` object.
    // This maintains the standard n8n data structure.
    json: {
      task_name: inputText,
      trans_type: inputText.slice(0, 5).toUpperCase(),
      amount: amountValue,
      jv_number : item.jv_number
    }
  };

  // Push the new item into the array that we will return.
  parsedItems.push(newItem);
}

// Crucial: The Code node must return the final array of output objects.
return parsedItems;

let items = $input.all().map(item => item.json);
let jv_num = $input.first().json.jv_number
let debitTotal = 0;
let creditTotal = 0;

for (const item of items) {

  let type = item.trans_type.trim().toUpperCase();

  if (type.startsWith("DEBI")) {
    debitTotal += Number(item.amount);
  }
  else if (type.startsWith("CREDI")) {
    creditTotal += Number(item.amount);
  }
}

let variance = debitTotal - creditTotal;
variance = Math.round(variance);
return [{
  debitTotal,
  creditTotal,
  variance,
  jv_num

}];

// Map over input items, normalize data access, build new objects
const mappedItems = items.map(item => {
  const data = item.json ?? item.$json; // handle both cases

  return {
    json: {
      task_name: data.task_name,
      trans_type: data.trans_type,
      sessionId: data.sessionId,
      jv_number: data.jv_number,
      task_name_with_jv: data.task_name_with_jv
    }
  };
});

// Filter out items without a valid task_name
const filteredItems = mappedItems.filter(item => {
  return item.json && item.json.task_name && item.json.task_name.trim() !== '';
});

// Return the filtered list as output of the Code node
return filteredItems;

